use eframe::egui;use std::sync::Arc;use std::collections::HashMap;use std::fs;use std::path::Path;use std::sync::atomic::{AtomicBool, Ordering};use std::thread;use std::time::Duration;use crate::main::{ForgeEditorApp, BottomTab};use crate::bitacora_singleton::get_validator_singleton;use crate::paperdoll::PaperdollCharacter;use crate::bitacora_manager::BitacoraManager;use crate::event_nodes::{EventNode, EventType};use crate::event_nodes_ui::EventNodeRenderer;use crate::cable_system::CableSystem;use crate::dialogue_editor::{DialogueManager, DialogueEditorRenderer};use crate::dialogue_editor_ui::DialogueEditorRenderer as DialogueRenderer;use crate::dialogue_export::DialogueExporter;use std::collections::HashMap;use std::fs;/// Gestor de eventos y diálogos con soporte en tiempo realpub struct EventDialogManager {    pub excel_manager: Option<crate::excel::ExcelManager>,    pub is_excel_loaded: bool,    pub excel_path: Option<String>,    pub current_event_filter: String,    pub current_dialog_filter: String,    pub selected_event: Option<String>,    pub selected_dialog: Option<String>,    pub language: String,    pub is_dialog_open: bool,    pub dialog_history: Vec<String>,    pub is_watching: bool,    pub watch_thread: Option<thread::JoinHandle<()>>,    pub should_stop_watching: Arc<AtomicBool>,    pub bitacora_log: Vec<String>,    pub temp_file_path: Option<String>,    pub bitacora_manager: BitacoraManager,    pub event_node_manager: Option<crate::event_node_manager::EventNodeManager>,    pub bottom_tab: BottomTab,    pub dialogue_renderer: Option<DialogueRenderer>,}impl Default for EventDialogManager {    fn default() -> Self {        Self {            excel_manager: None,            is_excel_loaded: false,            excel_path: None,            current_event_filter: "".to_string(),            current_dialog_filter: "".to_string(),            selected_event: None,            selected_dialog: None,            language: "es".to_string(),            is_dialog_open: false,            dialog_history: Vec::new(),            is_watching: false,            watch_thread: None,            should_stop_watching: Arc::new(AtomicBool::new(false)),            temp_file_path: None,            bitacora_manager: BitacoraManager::default(),            event_node_manager: Some(crate::event_node_manager::EventNodeManager::new()),            bottom_tab: BottomTab::EventNodes,            dialogue_renderer: Some(DialogueRenderer::new()),        }    }}impl EventDialogManager {    /// Cargar Excel con eventos y diálogos    pub fn load_excel(&mut self, path: Option<String>) {        if let Some(p) = path {            self.excel_manager = Some(crate::excel::ExcelManager::default());            if let Some(ref mut manager) = self.excel_manager {                manager.init(Some(p));                if let Ok(()) = manager.load() {                    self.is_excel_loaded = true;                    // Actualizar validador con referencias cargadas                    self.update_validator();                }            }            // Inicializar event_node_manager si no está inicializado            if self.event_node_manager.is_none() {                self.event_node_manager = Some(crate::event_node_manager::EventNodeManager::new());            }        }    }        /// Cambiar entre pestañas de Event Nodes y Events    pub fn set_bottom_tab(&mut self, tab: BottomTab) {        self.bottom_tab = tab;    }        pub fn get_bottom_tab(&self) -> BottomTab {        self.bottom_tab    }    /// Mostrar panel del Event Forge    pub fn show_event_forge_panel(&mut self, ui: &mut egui::Ui) {        ui.heading(egui::RichText::new("⚡ Event Forge").font(egui::FontId::proportional(16.0)));                // Tab de nodos de evento        ui.horizontal(|ui| {            ui.selectable_label(self.current_bottom_tab == BottomTab::EventNodes, "🔗 Event Nodes");            ui.selectable_label(self.current_bottom_tab == BottomTab::EventForge, "📊 Events");        });                if self.current_bottom_tab == BottomTab::EventNodes {            self.render_event_nodes_panel(ui);        } else {            // Controles superiores            ui.horizontal(|ui| {                if ui.add(egui::Button::new("📊 Load Excel").fill(egui::Color32::from_rgba_premultiplied(100, 150, 255, 200))).clicked() {                    let path = rfd::FileDialog::new().set_title("Load Excel File (.xlsx)").add_filter("Excel Files", &["xlsx"]).pick_file();                    if let Some(p) = path {                        self.load_excel(Some(p.to_string_lossy().to_string()));                        self.bitacora_manager.log(format!("📊 Excel loaded: {}", p.to_string_lossy()));                    }                }                ui.add_space(5.0);                if ui.add(egui::Button::new("🔄 Refresh").fill(egui::Color32::from_rgba_premultiplied(100, 150, 255, 200))).clicked() {                    self.refresh_events();                    self.bitacora_manager.log("🔄 Events refreshed");                }                ui.add_space(5.0);                if ui.add(egui::Button::new("👁️ Watch").fill(egui::Color32::from_rgba_premultiplied(100, 150, 255, 200))).clicked() {                    self.toggle_watch();                }            });                        ui.add_space(10.0);                        // Pestañas de Events y Dialogues            ui.horizontal(|ui| {                ui.selectable_label(self.current_bottom_tab == BottomTab::EventForge, "📊 Events");                ui.selectable_label(self.current_bottom_tab == BottomTab::DialogueEditor, "💬 Dialogues");            });                        if self.current_bottom_tab == BottomTab::EventForge {                ui.add_space(5.0);                                // Filtros                ui.horizontal(|ui| {                    ui.label(egui::RichText::new("Filter:").color(egui::Color32::WHITE));                    ui.add(egui::TextEdit::singleline(&mut self.current_event_filter).hint_text("Event name..."));                });                                ui.add_space(5.0);                                // Lista de eventos                if self.is_excel_loaded {                    self.render_event_list(ui);                    self.render_dialog_list(ui);                    self.render_selected_event(ui);                } else {                    ui.label(egui::RichText::new("⚠️ No Excel file loaded").color(egui::Color32::YELLOW));                    ui.label(egui::RichText::new("Click 'Load Excel' to load events and dialogs").color(egui::Color32::GRAY));                }            } else {                // Editor de Diálogos                self.render_dialogue_editor(ui, &HashMap::new());            }        }    }        /// Renderizar panel de nodos de evento    fn render_event_nodes_panel(&mut self, ui: &mut egui::Ui) {        if let Some(ref mut event_node_manager) = self.event_node_manager {            let mut renderer = EventNodeRenderer::new();                        ui.horizontal(|ui| {                ui.selectable_label(self.bottom_tab == BottomTab::EventNodes, "🔗 Event Nodes");                ui.selectable_label(self.bottom_tab == BottomTab::EventForge, "📊 Events");            });                        if self.bottom_tab == BottomTab::EventNodes {                ui.heading(egui::RichText::new("🔗 Event Nodes").font(egui::FontId::proportional(16.0)));                                // Botones de acción                ui.horizontal(|ui| {                    if ui.add(egui::Button::new("➕ Add Node").fill(egui::Color32::from_rgb(0, 200, 100))).clicked() {                        let id = event_node_manager.create_node(EventType::OnStart, (0.0, 0.0));                        event_node_manager.set_selected_node(Some(id));                    }                    ui.add_space(5.0);                    if ui.add(egui::Button::new("▶️ Execute").fill(egui::Color32::from_rgb(255, 200, 0))).clicked() {                        event_node_manager.execute_all();                        self.bitacora_manager.log("▶️ All nodes executed");                    }                    ui.add_space(5.0);                    if ui.add(egui::Button::new("🔄 Reset").fill(egui::Color32::from_rgb(200, 100, 100))).clicked() {                        event_node_manager.graph.nodes.values_mut().for_each(|node| {                            node.execution_count = 0;                            node.last_executed = None;                        });                        self.bitacora_manager.log("🔄 Execution counts reset");                    }                });                                ui.add_space(10.0);                                // Lista de nodos                ui.heading(egui::RichText::new("📋 Nodes").font(egui::FontId::proportional(14.0)));                let nodes = event_node_manager.get_all_nodes();                if nodes.is_empty() {                    ui.label(egui::RichText::new("No nodes created").color(egui::Color32::GRAY));                    ui.label(egui::RichText::new("Click 'Add Node' to create nodes").color(egui::Color32::GRAY));                } else {                    for (id, node) in nodes {                        let is_selected = event_node_manager.selected_node.as_deref() == Some(id);                        let node_type_color = renderer.get_node_type_color(&node.event_type);                                                egui::Frame::none()                            .fill(node_type_color)                            .stroke(egui::Stroke { color: if is_selected { egui::Color32::WHITE } else { egui::Color32::BLACK }, width: 1.0 })                            .inner_margin(egui::Margin::same(5.0))                            .show(ui, |ui| {                                ui.horizontal(|ui| {                                    ui.label(RichText::new(&node.event_type).size(12.0));                                    ui.label(format!("Executions: {}", node.execution_count));                                    if ui.button("X").clicked() {                                        event_node_manager.delete_node(id);                                        self.bitacora_manager.log(format!("🗑️ Node deleted: {}", id));                                    }                                });                            });                    }                }                                ui.add_space(10.0);                                // Nodos seleccionados                if let Some(selected_id) = &event_node_manager.selected_node {                    if let Some(node) = event_node_manager.get_node(selected_id) {                        ui.heading(egui::RichText::new("🎯 Selected Node").font(egui::FontId::proportional(14.0)));                        renderer.render_node_editor(node, renderer.get_node_type_color(&node.event_type));                    }                }            }        }    }        /// Renderizar editor de diálogos    pub fn render_dialogue_editor(&mut self, ui: &mut egui::Ui, dialogues: &HashMap<String, Dialogue>) {        if let Some(ref mut renderer) = self.dialogue_renderer {            renderer.render_dialogue_editor(ui, dialogues);        }}        /// Renderizar lista de eventos    fn render_event_list(&self, ui: &mut egui::Ui) {        ui.heading(egui::RichText::new("📋 Events").font(egui::FontId::proportional(14.0)));        if let Some(ref events) = self.excel_manager {            let events_read = events.events.read().unwrap();            if events_read.is_empty() {                ui.label(egui::RichText::new("No events loaded").color(egui::Color32::GRAY));                return;            }            for (event_id, event_data) in events_read.iter() {                let is_selected = self.selected_event.as_deref() == Some(event_id);                let label = ui.selectable_label(is_selected, format!("🔗 {}", event_data));                if label.clicked() {                    self.selected_event = Some(event_id.clone());                    self.bitacora_manager.log(format!("📋 Event selected: {}", event_data));                }            }        }    }        /// Renderizar lista de diálogos    fn render_dialog_list(&self, ui: &mut egui::Ui) {        ui.heading(egui::RichText::new("💬 Dialogs").font(egui::FontId::proportional(14.0)));        if let Some(ref events) = self.excel_manager {            let dialogs_read = events.dialogs.read().unwrap();            if dialogs_read.is_empty() {                ui.label(egui::RichText::new("No dialogs loaded").color(egui::Color32::GRAY));                return;            }            for (dialog_id, dialog_data) in dialogs_read.iter() {                let is_selected = self.selected_dialog.as_deref() == Some(dialog_id);                let label = ui.selectable_label(is_selected, format!("📝 {}", dialog_data));                if label.clicked() {                    self.selected_dialog = Some(dialog_id.clone());                    self.bitacora_manager.log(format!("💬 Dialog selected: {}", dialog_data));                }            }        }    }        /// Renderizar evento seleccionado    fn render_selected_event(&self, ui: &mut egui::Ui) {        ui.heading(egui::RichText::new("🎯 Selected Event").font(egui::FontId::proportional(14.0)));        if let Some(event_id) = &self.selected_event {            if let Some(ref events) = self.excel_manager {                let events_read = events.events.read().unwrap();                if let Some(event_data) = events_read.get(event_id) {                    ui.label(egui::RichText::new(format!("Event: {}", event_data)).color(egui::Color32::WHITE));                    ui.add_space(5.0);                    ui.label(egui::RichText::new("📍 Status: Active").color(egui::Color32::GREEN));                    ui.add_space(5.0);                    ui.horizontal(|ui| {                        if ui.add(egui::Button::new("▶️ Execute").fill(egui::Color32::from_rgba_premultiplied(50, 150, 255, 200))).clicked() {                            self.bitacora_manager.log(format!("▶️ Executing event: {}", event_data));                        }                    });                }            }        } else {            ui.label(egui::RichText::new("No event selected").color(egui::Color32::GRAY));        }    }        /// Actualizar eventos    pub fn refresh_events(&mut self) {        if let Some(ref mut manager) = self.excel_manager {            if let Ok(()) = manager.load() {                self.is_excel_loaded = true;                self.bitacora_manager.log("🔄 Events refreshed");            }        }    }        /// Iniciar/detener watch mode    pub fn toggle_watch(&mut self) {        self.is_watching = !self.is_watching;        if self.is_watching {            self.bitacora_manager.log("👁️ Watch mode started");        } else {            self.bitacora_manager.log("👁️ Watch mode stopped");        }    }        /// Actualizar validador con referencias del Excel    pub fn update_validator(&self) {        if let Some(ref manager) = self.excel_manager {            let mut excel_references = HashMap::new();                        // Agregar referencias de eventos            if let Some(ref events) = manager.events.read().unwrap() {                for event_id in events.keys() {                    excel_references.insert(event_id.clone(), "event".to_string());                }            }                        // Agregar referencias de diálogos            if let Some(ref dialogs) = manager.dialogs.read().unwrap() {                for dialog_id in dialogs.keys() {                    excel_references.insert(dialog_id.clone(), "dialog".to_string());                }            }                        // Agregar referencias de actores            if let Some(ref actors) = manager.actors.read().unwrap() {                for actor_id in actors.keys() {                    excel_references.insert(actor_id.clone(), "actor".to_string());                }            }                        // Agregar referencias de variables            if let Some(ref variables) = manager.variables.read().unwrap() {                for var_id in variables.keys() {                    excel_references.insert(var_id.clone(), "var".to_string());                }            }                        // Agregar referencias de escenas            if let Some(ref scenes) = manager.scenes.read().unwrap() {                for scene_id in scenes.keys() {                    excel_references.insert(scene_id.clone(), "scene".to_string());                }            }                        // Actualizar validador (usando Arc)            if let Some(ref validator) = crate::main::ForgeEditorApp::get_validator() {                validator.load_excel_references(&excel_references);                validator.validate_bitacora();            }        }    }    /// Abrir diálogo    pub fn open_dialog(&mut self, dialog_id: &str) {        self.selected_dialog = Some(dialog_id.to_string());        self.is_dialog_open = true;    }    /// Cerrar diálogo    pub fn close_dialog(&mut self) {        self.is_dialog_open = false;        self.selected_dialog = None;    }    /// Obtener lista de eventos    pub fn get_events(&self) -> Vec<String> {        if let Some(ref manager) = self.excel_manager {            let events = manager.events.read().unwrap();            events.keys().cloned().collect()        } else {            Vec::new()        }    }    /// Obtener lista de diálogos    pub fn get_dialogs(&self) -> Vec<String> {        if let Some(ref manager) = self.excel_manager {            let dialogs = manager.dialogs.read().unwrap();            dialogs.keys().cloned().collect()        } else {            Vec::new()        }    }    /// Obtener texto de evento    pub fn get_event_text(&self, event_id: &str) -> String {        if let Some(ref manager) = self.excel_manager {            if let Some(event) = manager.events.read().unwrap().get(event_id) {                if let Some(texts) = event.get("texts") {                    if let Some(texts_list) = texts.get(&self.language) {                        if let Some(texts_vec) = texts_list.as_list() {                            if let Some(text) = texts_vec.first() {                                return text.as_str().unwrap_or("").to_string();                            }                        }                    }                }            }        }        "No text".to_string()    }    /// Obtener triggers de evento    pub fn get_event_triggers(&self, event_id: &str) -> Vec<String> {        if let Some(ref manager) = self.excel_manager {            if let Some(event) = manager.events.read().unwrap().get(event_id) {                if let Some(triggers) = event.get("triggers") {                    if let Some(triggers_list) = triggers.get("list") {                        if let Some(triggers_vec) = triggers_list.as_list() {                            return triggers_vec.iter().map(|t| t.as_str().unwrap_or("").to_string()).collect();                        }                    }                }            }        }        Vec::new()    }    /// Obtener IDs de diálogos de un evento    pub fn get_event_dialog_ids(&self, event_id: &str) -> Vec<String> {        if let Some(ref manager) = self.excel_manager {            if let Some(event) = manager.events.read().unwrap().get(event_id) {                if let Some(dialog) = event.get("dialog") {                    if let Some(dialog_list) = dialog.get("list") {                        if let Some(dialogs_vec) = dialog_list.as_list() {                            return dialogs_vec.iter().map(|d| d.as_str().unwrap_or("").to_string()).collect();                        }                    }                }            }        }        Vec::new()    }    /// Obtener personaje actual    pub fn get_paperdoll_character(&self) -> Option<&PaperdollCharacter> {        self.event_dialog_manager.paperdoll_character.as_ref()    }    /// Obtener opciones de diálogo    pub fn get_dialog_options(&self, dialog_id: &str) -> Vec<String> {        if let Some(ref manager) = self.excel_manager {            if let Some(dialog) = manager.dialogs.read().unwrap().get(dialog_id) {                if let Some(options) = dialog.get("options") {                    if let Some(options_list) = options.get("list") {                        if let Some(options_vec) = options_list.as_list() {                            return options_vec.iter().map(|o| o.as_str().unwrap_or("").to_string()).collect();                        }                    }                }            }        }        Vec::new()    }    /// Cambiar idioma    pub fn set_language(&mut self, lang: &str) {        self.language = lang.to_string();    }    /// Iniciar watcher de archivos para actualizaciones en tiempo real    pub fn start_watching(&mut self) {        if self.is_watching {            return;        }        if let Some(ref path) = self.excel_path {            self.is_watching = true;            self.should_stop_watching.store(false, Ordering::SeqCst);                        let path_clone = path.clone();            let excel_manager = self.excel_manager.clone();            let should_stop = self.should_stop_watching.clone();            let temp_path_clone = self.temp_file_path.clone();                        self.watch_thread = Some(thread::spawn(move || {                let mut last_modified = fs::metadata(&path_clone)                    .ok()                    .and_then(|m| m.modified().ok())                    .unwrap_or(std::time::SystemTime::now());                let mut temp_path = temp_path_clone;                                loop {                    if should_stop.load(Ordering::SeqCst) {                        break;                    }                                        // Verificar archivo original                    match fs::metadata(&path_clone) {                        Ok(m) => {                            if let Ok(modified) = m.modified() {                                if modified > last_modified {                                    last_modified = modified;                                    println!("🔄 Excel modificado: {}", path_clone);                                                                        if let Some(ref mut manager) = excel_manager {                                        let _ = manager.load();                                        println!("✅ Excel recargado en tiempo real");                                    }                                }                            }                        }                        Err(_) => {                            // Archivo eliminado                            break;                        }                    }                                        // Verificar archivo temporal                    if let Some(ref tp) = temp_path {                        match fs::metadata(tp) {                            Ok(m) => {                                if let Ok(modified) = m.modified() {                                    if modified > last_modified {                                        last_modified = modified;                                        println!("🔄 Temp file modificado: {}", tp);                                                                                if let Some(ref mut manager) = excel_manager {                                            let _ = manager.load();                                            println!("✅ Excel recargado desde temp file");                                        }                                    }                                }                            }                            Err(_) => {                                // Temp file eliminado                                temp_path = None;                            }                        }                    }                                        thread::sleep(Duration::from_secs(1));                }            }));        }    }    /// Detener watcher de archivos    pub fn stop_watching(&mut self) {        if let Some(ref thread) = self.watch_thread {            self.should_stop_watching.store(true, Ordering::SeqCst);            thread.join().ok();        }        self.is_watching = false;        self.watch_thread = None;        self.temp_file_path = None;    }    /// Obtener estado del watcher    pub fn is_watching(&self) -> bool {        self.is_watching    }    /// Agregar entrada a la bitácora    pub fn log(&mut self, message: &str) {        let timestamp = chrono::Local::now().format("%H:%M:%S");        self.bitacora_log.push(format!("[{}] {}", timestamp, message));    }    /// Limpiar bitácora    pub fn clear_log(&mut self) {        self.bitacora_log.clear();    }    /// Crear archivo temporal para live updates    pub fn create_temp_file(&self) -> Option<String> {        if let Some(ref path) = self.excel_path {            let ext = if path.ends_with(".xlsx") { "xlsx" } else if path.ends_with(".csv") { "csv" } else { "csv" };                        let temp_dir = std::env::temp_dir();            let temp_path = temp_dir.join(format!("forge_temp_{}.{}", std::process::id(), ext));                        // Copiar archivo original a temporal            if let Ok(mut file) = std::fs::File::open(path) {                if let Ok(mut temp_file) = std::fs::File::create(&temp_path) {                    if std::io::copy(&mut file, &mut temp_file).is_ok() {                        return Some(temp_path.to_string_lossy().to_string());                    }                }            }        }        None    }    /// Guardar cambios en archivo temporal    pub fn save_to_temp(&mut self, temp_path: &str) {        if let Some(ref manager) = self.excel_manager {            if let Ok(content) = std::fs::read_to_string(temp_path) {                let events = crate::excel::csv_parser::parse_csv_events(&content).ok();                let dialogs = crate::excel::csv_parser::parse_csv_dialogs(&content).ok();                                if let Some(ref mut mgr) = self.excel_manager {                    mgr.events.write().unwrap().clear();                    mgr.dialogs.write().unwrap().clear();                                        if let Some(events) = events {                        mgr.events.write().unwrap().insert(temp_path.to_string(), events);                    }                    if let Some(dialogs) = dialogs {                        mgr.dialogs.write().unwrap().insert(temp_path.to_string(), dialogs);                    }                }            }        }        self.temp_file_path = Some(temp_path.to_string());    }    /// Validar la bitácora con el linter    pub fn validate_bitacora(&mut self) {        let validator = crate::bitacora_singleton::get_validator_singleton().get_validator();        validator.validate_and_get_results();        self.log("✅ Validación completada");    }    /// Analizar coherencia de actores (plot hole detector)    pub fn analyze_actor_coherence(&mut self) {        let events = self.get_events();        let dialogs = self.get_dialogs();                let mut inconsistencies = Vec::new();                // Analizar cada evento        for event_id in &events {            let triggers = self.get_event_triggers(event_id);            let dialog_ids = self.get_event_dialog_ids(event_id);                        // Verificar si los diálogos referenciados existen            for dialog_id in &dialog_ids {                if !dialogs.contains_key(dialog_id) {                    inconsistencies.push(format!(                        "⚠️ Evento '{}' referencia diálogo '{}' que no existe",                        event_id, dialog_id                    ));                }            }                        // Verificar coherencia de actores en triggers            for trigger in &triggers {                if trigger.contains("actor:") {                    let actor_id = trigger.split("actor:").nth(1).unwrap_or("").trim();                    if let Some(actor) = self.get_paperdoll_character() {                        let available_actors = actor.get_all_actors();                        if !available_actors.contains(actor_id) {                            inconsistencies.push(format!(                                "⚠️ Actor '{}' en evento '{}' no pertenece al personaje actual",                                actor_id, event_id                            ));                        }                    }                }            }        }                // Verificar coherencia en diálogos        for dialog_id in &dialogs.keys() {            let options = self.get_dialog_options(dialog_id);            for option in &options {                if option.contains("actor:") {                    let actor_id = option.split("actor:").nth(1).unwrap_or("").trim();                    if let Some(actor) = self.get_paperdoll_character() {                        let available_actors = actor.get_all_actors();                        if !available_actors.contains(actor_id) {                            inconsistencies.push(format!(                                "⚠️ Actor '{}' en diálogo '{}' no pertenece al personaje actual",                                actor_id, dialog_id                            ));                        }                    }                }            }        }                // Reportar inconsistencias        if !inconsistencies.is_empty() {            for msg in &inconsistencies {                crate::bitacora_singleton::get_validator_singleton().get_validator().add_warning(msg);            }            self.log(format!("🔍 Análisis de coherencia: {} inconsistencias encontradas", inconsistencies.len()));        } else {            self.log("✅ Coherencia de actores: todo correcto");        }    }    /// Analizar variables declaradas y usadas    pub fn analyze_variables(&mut self) {        let events = self.get_events();                let mut used_vars = HashMap::new();        let var_pattern = Regex::new(r"\{var:([^}]+)\}").unwrap();                // Analizar cada evento        for event_id in &events {            let text = self.get_event_text(event_id);                        // Buscar variables en el texto del evento            for cap in var_pattern.captures_iter(&text) {                if let Some(var_name) = cap.get(1) {                    used_vars.entry(var_name.as_str().to_string()).or_insert(0);                }            }                        // Buscar variables en triggers            let triggers = self.get_event_triggers(event_id);            for trigger in &triggers {                for cap in var_pattern.captures_iter(trigger) {                    if let Some(var_name) = cap.get(1) {                        used_vars.entry(var_name.as_str().to_string()).or_insert(0);                    }                }            }        }                // Reportar variables usadas        if !used_vars.is_empty() {            self.log(format!("📊 Variables usadas: {}", used_vars.len()));            for (var_name, count) in &used_vars {                self.log(format!("  - {}: {} veces", var_name, count));            }        }    }    /// Guardar nota vinculada a un evento    pub fn save_note_for_event(&mut self, event_id: &str, text: &str) {        let note_id = self.bitacora_manager.add_entry(text, Some(event_id.to_string()));        self.log(format!("📝 Nota guardada ({}): vinculada a evento {}", note_id, event_id));        note_id    }    /// Obtener notas para el evento seleccionado    pub fn get_notes_for_selected_event(&self) -> Vec<&BitacoraManager::BitacoraEntry> {        if let Some(ref event_id) = self.selected_event {            self.bitacora_manager.get_related_entries(event_id)        } else {            Vec::new()        }    }    /// Guardar nota para el evento seleccionado    pub fn save_note_for_selected_event(&mut self, text: &str) {        if let Some(ref event_id) = self.selected_event {            let note_id = self.save_note_for_event(event_id, text);            self.log(format!("✅ Nota {} guardada para evento {}", note_id, event_id));        }    }    /// Obtener todas las notas de la bitácora    pub fn get_all_notes(&self) -> Vec<&BitacoraManager::BitacoraEntry> {        self.bitacora_manager.get_active_entries()    }    /// Obtener notas filtradas    pub fn get_filtered_notes(&self, filter: &str) -> Vec<&BitacoraManager::BitacoraEntry> {        self.bitacora_manager.get_filtered_entries(filter)    }    /// Limpiar bitácora    pub fn clear_bitacora(&mut self) {        self.bitacora_manager.clear();        self.log("🗑️ Bitácora limpia");    }    /// Analizar coherencia narrativa temporal (detectar interacciones con personajes inactivos)    pub fn analyze_narrative_coherence(&mut self) {        self.log("📊 Analizando coherencia narrativa temporal...");                let events = self.get_events();        let mut temporal_warnings = Vec::new();                // Ordenar eventos por ID (asumiendo que el orden alfabérico refleja el orden temporal)        let mut sorted_events: Vec<_> = events.iter().collect();        sorted_events.sort_by(|a, b| a.cmp(b));                // Analizar cada evento en orden        for event_idx in 0..sorted_events.len() {            let (event_id, _) = sorted_events[event_idx];            let triggers = self.get_event_triggers(event_id);                        // Verificar si el evento marca algún actor como inactivo/muerto            let inactive_actors = self.get_inactive_actors_from_event(event_id);                        if !inactive_actors.is_empty() {                self.log(format!("🔴 Evento '{}' marca actores inactivos: {:?}", event_id, inactive_actors));            }                        // Verificar eventos posteriores que interactúen con actores inactivos            for future_idx in (event_idx + 1)..sorted_events.len() {                let (future_event_id, _) = sorted_events[future_idx];                let future_triggers = self.get_event_triggers(future_event_id);                                // Verificar si el evento futuro interactúa con actores inactivos                let interacting_actors = self.get_interacting_actors_from_triggers(&future_triggers);                                for actor_id in &interacting_actors {                    if inactive_actors.contains(actor_id) {                        temporal_warnings.push(format!(                            "⚠️ [{} → {}] Interacción con actor inactivo '{}'. El actor fue marcado como inactivo en '{}' pero interactúa en '{}'",                            event_id, future_event_id, actor_id, event_id, future_event_id                        ));                    }                }            }        }                // Reportar advertencias        if !temporal_warnings.is_empty() {            self.log(format!("🚨 {} advertencias de coherencia narrativa detectadas", temporal_warnings.len()));            for warning in &temporal_warnings {                self.log(warning.clone());            }        } else {            self.log("✅ Coherencia narrativa temporal: OK");        }                temporal_warnings    }    /// Obtener actores marcados como inactivos en un evento    fn get_inactive_actors_from_event(&self, event_id: &str) -> Vec<String> {        let triggers = self.get_event_triggers(event_id);        let mut inactive_actors = Vec::new();                for trigger in &triggers {            // Buscar patrones como "actor:X:inactive", "actor:X:dead", "actor:X:dead_body"            if trigger.contains("actor:") {                let parts: Vec<&str> = trigger.split("actor:").nth(1).unwrap_or("").split(':').collect();                if parts.len() >= 2 {                    let actor_id = parts[0].trim();                    let status = parts[1].trim().to_lowercase();                                        // Si el estado es inactivo, muerto, cuerpo, etc.                    if status.contains("inactive") || status.contains("dead") || status.contains("body") || status.contains("corpse") {                        if !inactive_actors.contains(actor_id) {                            inactive_actors.push(actor_id.to_string());                        }                    }                }            }        }                inactive_actors    }    /// Obtener actores que interactúan en triggers    fn get_interacting_actors_from_triggers(&self, triggers: &[String]) -> Vec<String> {        let mut interacting_actors = Vec::new();                for trigger in triggers {            if trigger.contains("actor:") {                let parts: Vec<&str> = trigger.split("actor:").nth(1).unwrap_or("").split(':').collect();                if parts.len() >= 2 {                    let actor_id = parts[0].trim();                    // Solo incluir si no es un estado (es un ID de actor válido)                    if !actor_id.contains("inactive") && !actor_id.contains("dead") && !actor_id.contains("body") {                        if !interacting_actors.contains(actor_id) {                            interacting_actors.push(actor_id.to_string());                        }                    }                }            }        }                interacting_actors    }    /// Guardar nota en la bitácora interactiva    pub fn add_note(&mut self, text: &str, related_to: Option<String>) -> String {        self.bitacora_manager.add_entry(text, related_to)    }        /// Exportar diálogo seleccionado a JSON    pub fn export_dialogue_to_json(&self, dialogue_id: &str) -> String {        if let Some(dialogue) = self.dialogue_manager.get_dialogue(dialogue_id) {            DialogueExporter::export_to_json(dialogue)        } else {            "Dialog not found".to_string()        }    }        /// Exportar diálogo seleccionado a CSV    pub fn export_dialogue_to_csv(&self, dialogue_id: &str) -> String {        if let Some(dialogue) = self.dialogue_manager.get_dialogue(dialogue_id) {            DialogueExporter::export_to_csv(dialogue)        } else {            "Dialog not found".to_string()        }    }        /// Exportar diálogo seleccionado a código Rust    pub fn export_dialogue_to_rust(&self, dialogue_id: &str) -> String {        if let Some(dialogue) = self.dialogue_manager.get_dialogue(dialogue_id) {            DialogueExporter::export_to_rust(dialogue)        } else {            "Dialog not found".to_string()        }    }        /// Cargar variables de diálogo    pub fn load_dialogue_variables(&mut self, dialogue_id: &str) {        if let Some(dialogue) = self.dialogue_manager.get_dialogue_mut(dialogue_id) {            for (var_id, var) in &dialogue.variables {                self.dialogue_manager.variables.insert(var.clone(), var.clone());            }            self.bitacora_manager.log(format!("📊 Variables cargadas para diálogo: {}", dialogue_id));        }    }        /// Cambiar idioma del diálogo    pub fn change_dialogue_language(&mut self, dialogue_id: &str, lang: &str) {        if let Some(dialogue) = self.dialogue_manager.get_dialogue_mut(dialogue_id) {            dialogue.language = lang.to_string();            self.bitacora_manager.log(format!("🌐 Idioma cambiado a: {}", lang));        }    }        /// Obtener texto de diálogo en idioma especificado    pub fn get_dialogue_text(&self, dialogue_id: &str, lang: &str) -> String {        if let Some(dialogue) = self.dialogue_manager.get_dialogue(dialogue_id) {            dialogue.lines.iter()                .filter(|l| !l.is_hidden)                .map(|l| &l.text)                .collect::<Vec<_>>()                .join(" ")        } else {            "Dialog not found".to_string()        }    }        /// Renderizar editor de diálogos completo en panel    pub fn render_dialogue_editor_panel(&mut self, ui: &mut egui::Ui, dialogues: &HashMap<String, Dialogue>) {        if let Some(ref mut renderer) = self.dialogue_renderer {            renderer.render_dialogue_editor(ui, dialogues);        }    }    /// Obtener nota por ID    pub fn get_note(&self, id: &str) -> Option<&BitacoraManager::BitacoraEntry> {        self.bitacora_manager.get_entry(id)    }    /// Actualizar nota    pub fn update_note(&mut self, id: &str, new_text: &str) {        self.bitacora_manager.update_entry(id, new_text);        self.log(format!("📝 Nota {} actualizada", id));    }    /// Eliminar nota    pub fn remove_note(&mut self, id: &str) {        self.bitacora_manager.remove_entry(id);        self.log(format!("🗑️ Nota {} eliminada", id));    }    /// Obtener entradas relacionadas con un evento    pub fn get_notes_for_event(&self, event_id: &str) -> Vec<&BitacoraManager::BitacoraEntry> {        self.bitacora_manager.get_related_entries(event_id)    }}/// UI Panel para Eventos y Diálogospub fn event_dialog_panel(app: &mut ForgeEditorApp, ui: &mut egui::Ui) {    let mut panel = egui::PanelContainer::new("Event Dialog Panel")        .resizable(true)        .min_size([300.0, 400.0])        .build(ui);    panel.show_viewport_contents(|ui| {        egui::ScrollArea::vertical().show(ui, |ui| {            let mut show_excel_dialog = false;            let mut selected_lang = app.event_dialog_manager.language.clone();            // Header            egui::TopBottomPanel::top("event_dialog_header").show(ui, |ui| {                egui::warn::warn(                    "📊 Eventos & Diálogos",                    "Excel/CSV",                    "Live Updates",                );                ui.horizontal(|ui| {                    if ui.button("📁 Cargar Excel").clicked() {                        show_excel_dialog = true;                    }                                        if ui.button("🔄 Live Updates").clicked() {                        if app.event_dialog_manager.is_watching {                            app.event_dialog_manager.stop_watching();                        } else {                            app.event_dialog_manager.start_watching();                        }                    }                                        if ui.button("📂 Temp File").clicked() {                        if let Some(temp_path) = app.event_dialog_manager.create_temp_file() {                            app.event_dialog_manager.log(&format!("📂 Temp file created: {}", temp_path));                            app.event_dialog_manager.save_to_temp(&temp_path);                            app.event_dialog_manager.log(&format!("✅ Temp file saved and watching automatically"));                        }                    }                                        ui.add_space(5.0);                    if ui.button("🔍 Validar").clicked() {                        app.event_dialog_manager.validate_bitacora();                    }                                        ui.add_space(5.0);                    if ui.button("🎭 Analizar Coherencia").clicked() {                        app.event_dialog_manager.analyze_actor_coherence();                    }                                        ui.add_space(5.0);                    if ui.button("📊 Analizar Variables").clicked() {                        app.event_dialog_manager.analyze_variables();                    }                                        ui.add_space(5.0);                    if ui.button("⏰ Analizar Coherencia Narrativa").clicked() {                        app.event_dialog_manager.analyze_narrative_coherence();                    }                });                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {                    for lang in ["es", "en", "fr", "de"] {                        if ui.selectable_label(selected_lang == lang, format!("🌐 {}", lang)).clicked() {                            selected_lang = lang.to_string();                        }                    }                });            });            // Excel Status            egui::TopBottomPanel::top("event_excel_status").show(ui, |ui| {                let status = if app.event_dialog_manager.is_excel_loaded {                    "✅ Excel cargado"                } else {                    "⚠️ Carga un Excel/CSV para ver eventos"                };                                let watch_status = if app.event_dialog_manager.is_watching {                    " 🔴 Watch activo (Live Updates)"                } else {                    " ⏸️ Watch pausado"                };                                egui::Label::new(format!("{}{}", status, watch_status)).ui(ui);            });            // Eventos            egui::TopBottomPanel::top("event_list").show(ui, |ui| {                ui.heading("🎯 Eventos");                let events = app.event_dialog_manager.get_events();                let filtered_events: Vec<_> = if app.event_dialog_manager.current_event_filter.is_empty() {                    events                } else {                    events.iter().filter(|e| e.contains(&app.event_dialog_manager.current_event_filter)).cloned().collect()                };                for event_id in filtered_events {                    let text = app.event_dialog_manager.get_event_text(&event_id);                    let triggers = app.event_dialog_manager.get_event_triggers(&event_id);                                        let mut is_selected = app.event_dialog_manager.selected_event == Some(event_id.clone());                    let response = ui.selectable_label(is_selected, format!("🔹 {} ({} triggers)", event_id, triggers.len()));                    if response.clicked() {                        app.event_dialog_manager.selected_event = Some(event_id.clone());                    }                    ui.label(format!("  Text: {}", text));                }            });            // Diálogos            egui::TopBottomPanel::top("dialog_list").show(ui, |ui| {                ui.heading("💬 Diálogos");                let dialogs = app.event_dialog_manager.get_dialogs();                let filtered_dialogs: Vec<_> = if app.event_dialog_manager.current_dialog_filter.is_empty() {                    dialogs                } else {                    dialogs.iter().filter(|d| d.contains(&app.event_dialog_manager.current_dialog_filter)).cloned().collect()                };                for dialog_id in filtered_dialogs {                    let options = app.event_dialog_manager.get_dialog_options(&dialog_id);                                        let mut is_selected = app.event_dialog_manager.selected_dialog == Some(dialog_id.clone());                    let response = ui.selectable_label(is_selected, format!("🔹 {} ({} options)", dialog_id, options.len()));                    if response.clicked() {                        app.event_dialog_manager.selected_dialog = Some(dialog_id.clone());                        app.event_dialog_manager.open_dialog(&dialog_id);                    }                }            });            // Diálogo Activo            if app.event_dialog_manager.is_dialog_open {                egui::TopBottomPanel::top("active_dialog").show(ui, |ui| {                    ui.heading("💬 Diálogo Actual");                    if let Some(dialog_id) = &app.event_dialog_manager.selected_dialog {                        // Aquí podrías mostrar el texto del diálogo                        ui.label(format!("Dialog ID: {}", dialog_id));                    }                });            }            // Bitácora            egui::TopBottomPanel::top("bitacora_panel").show(ui, |ui| {                ui.heading("📝 Bitácora");                                let logs = if app.event_dialog_manager.bitacora_log.is_empty() {                    "No hay registros".to_string()                } else {                    app.event_dialog_manager.bitacora_log.last().unwrap().clone()                };                                egui::ScrollArea::vertical().show(ui, |ui| {                    ui.label(logs);                });                                ui.horizontal(|ui| {                    if ui.button("🗑️ Limpiar").clicked() {                        app.event_dialog_manager.clear_log();                    }                });            });        });    });    // Dialogo para seleccionar Excel    if show_excel_dialog {        egui::Window::new("📁 Seleccionar Excel").open(&mut show_excel_dialog).show(ui, |ui| {            if let Some(ref mut manager) = app.event_dialog_manager.excel_manager {                if let Err(e) = manager.load() {                    ui.label(format!("Error: {}", e));                }            }        });    }});
